tool_input.command:
node --input-type=module <<'EOF'
import { dashboard } from './src/reports.js';

const invoices = [
  // Draft invoices
  { status: 'draft', customerId: 'ACME', lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }], payments: [] },
  { status: 'draft', customerId: 'ACME', lines: [{ qty: 1, unitPrice: 500, vatRate: 0 }], payments: [] },

  // Issued invoices
  { status: 'issued', number: '001', customerId: 'ACME', dueDate: '2026-10-15', lines: [{ qty: 1, unitPrice: 5000, vatRate: 0 }], payments: [] },
  { status: 'issued', number: '002', customerId: 'TechCorp', dueDate: '2026-10-20', lines: [{ qty: 1, unitPrice: 8000, vatRate: 0 }], payments: [] },

  // Partially paid
  { status: 'partially_paid', customerId: 'ACME', dueDate: '2026-10-10', lines: [{ qty: 1, unitPrice: 3000, vatRate: 0 }], payments: [{ amount: 1000 }] },
  { status: 'partially_paid', customerId: 'StartUp', dueDate: '2026-10-05', lines: [{ qty: 1, unitPrice: 2000, vatRate: 0 }], payments: [{ amount: 800 }] },

  // Paid invoices
  { status: 'paid', customerId: 'BigCo', lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }], payments: [{ amount: 10000 }] },
];

const result = dashboard(invoices, '2026-10-12');

console.log('=== Invoice Dashboard ===\n');
console.log('Invoice Counts:');
console.log(`  Draft: ${result.counts.draft}`);
console.log(`  Issued: ${result.counts.issued}`);
console.log(`  Partially Paid: ${result.counts.partially_paid}`);
console.log(`  Paid: ${result.counts.paid}`);

console.log('\nOutstanding (Issued + Partially Paid):');
console.log(`  Total Due: €${(result.outstanding / 100).toFixed(2)}`);

console.log('\nOverdue Invoices:');
console.log(`  Count: ${result.overdue.count}`);
console.log(`  Amount: €${(result.overdue.amount / 100).toFixed(2)}`);

console.log('\nTop 3 Customers by Outstanding:');
result.topCustomers.forEach((customer, i) => {
  console.log(`  ${i + 1}. ${customer.customerId}: €${(customer.due / 100).toFixed(2)}`);
});
EOF
